package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import com.ruoyi.medical.persistence.mapper.*;import java.io.*;import java.time.*;import java.util.*;
/** Exact ownership scope, bounded live keyset. Listing visibility never represents execution eligibility. */
public final class RuntimeRetentionReads {
 private final EnterpriseAccess access;private final RuntimeRetentionMapper mapper;private final PermissionMapper permissions;private final ResourceReadAuthority resources;private final RuntimeRetentionAuthority authority;private final RuntimeRetentionSchema schema;private final PermissionSchema json;
 public RuntimeRetentionReads(EnterpriseAccess access,RuntimeRetentionMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,RuntimeRetentionAuthority authority,RuntimeRetentionSchema schema,PermissionSchema json){this.access=access;this.mapper=mapper;this.permissions=permissions;this.resources=resources;this.authority=authority;this.schema=schema;this.json=json;}
 public JsonNode read(ApplicationSessionIdentity.Verified actor,String context,String id){id(id);return access.execute(actor,a->checked(()->{current(a,context);var row=RuntimeRetentionAuthority.one(mapper.fixed(RuntimeRetentionAuthority.parameters("policyRevision",id)));if(!id.equals(row.policyRevision()))fail();resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),row.projectId()),"retention.read","RUNTIME_RETENTION_READING");return view(row);}));}
 public JsonNode list(ApplicationSessionIdentity.Verified actor,String context,String scope,String project,int limit,String after){if(!Set.of("ENTERPRISE","PROJECT").contains(scope)||limit<1||limit>20||scope.equals("PROJECT")!=(project!=null))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);if(project!=null)id(project);if(after!=null)id(after);return access.execute(actor,a->checked(()->{current(a,context);var grant=resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),project),"retention.read","RUNTIME_RETENTION_READING");var v=new HashMap<String,Object>();v.put("userId",a.actorId());v.put("projectId",project);v.put("after",after);v.put("limit",limit+1);var rows=mapper.list(v);if(rows.size()>limit+1)fail();var items=json.object().putArray("items");String previous=after;for(int i=0;i<Math.min(limit,rows.size());i++){var row=rows.get(i);if(!Objects.equals(project,row.projectId())||previous!=null&&previous.compareTo(row.policyRevision())>=0)fail();items.add(view(row));previous=row.policyRevision();}if(!grant.equals(resources.require(a,RuntimeRetentionAuthority.scope(a.context().tenant_id(),project),"retention.read","RUNTIME_RETENTION_READING")))throw new TenantAccessException(ErrorCode.SCOPE_STALE);var out=json.object().put("schema_version","1.0.0").put("scope",scope).put("pagination","LIVE_KEYSET").put("limit",limit);out.set("project_id",json.tree(project));out.set("current_context",json.tree(a.context()));out.set("items",items);out.set("next_after",json.tree(rows.size()>limit?previous:null));out.put("complete",rows.size()<=limit);out.put("listing_sha256",schema.hash(items));return schema.validate("RetentionList",out);}));}
 private JsonNode view(RuntimeRetentionMapper.Row row)throws IOException{var fixed=authority.verify(row);var state=authority.lifecycle(row);Instant now=permissions.databaseTime().toInstant(ZoneOffset.UTC);var request=fixed.required("request");String status=state.retiredAt()!=null&&!now.isBefore(Instant.parse(state.retiredAt()))?"RETIRED":!now.isBefore(Instant.parse(request.required("effective_until").textValue()))?"EXPIRED":now.isBefore(Instant.parse(request.required("effective_from").textValue()))?"SCHEDULED":"IN_EFFECT";var result=json.object().put("schema_version","1.0.0").put("content_sha256",row.contentHash()).put("revision",state.revision()).put("lifecycle",status).put("observed_at",now.toString());result.set("fixed",fixed);result.set("retirement_at",json.tree(state.retiredAt()));result.set("retirement_decision_id",json.tree(state.decisionId()));return schema.validate("RetentionView",result);}
 private static void id(String id){if(id==null||!id.matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"))throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);}
 private interface Work<T>{T get()throws IOException;}private static <T>T checked(Work<T>w){try{return w.get();}catch(IOException e){throw new SchemaRejection(ErrorCode.CONTENT_MISMATCH);}}private static void current(EnterpriseAccess.Admission a,String c){if(!a.context().context_revision().equals(c))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}private static void fail(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
